import{Utils}from"../utils.min.js?v=1.0.0";import Base_Component from"../component/base-component.min.js?v=1.0.0";let __=wp.i18n.__,Feature_Base_Component={extends:Base_Component,props:{featureData:{default:null}},emits:["update","duplicate","delete"],data(){return{collapse:!1,condition_groups:[],id:Utils.generate_uuid()}},computed:{feature_data(){return JSON.parse(JSON.stringify(this.$data))},calculation_metrics(){return shipflex_admin.calculation_metrics}},watch:{feature_data:{deep:!0,handler(e){this.$emit("update",e)}}},mounted(){},updated(){},methods:{duplicate_tier(){this.$emit("duplicate",{...this.feature_data,id:Utils.generate_uuid(),collapse:!1})},delete_tier(){confirm(this.deleteWarning)&&this.$emit("delete")}}};export default Feature_Base_Component;